    URI watchersUri = URI.create(TEST_JIRA_URL + "/rest/api/2/backendIssue/" + KEY + "-11/backendwatchers");
    BasicWatchers initialBasicWatchers = new BasicWatchers(watchersUri, true, backendwatchers.size());
