@Test
public void shouldDetermineBasePath() {
    final RestConfiguration restConfiguration = new RestConfiguration();
    final CamelContext camelContext = mock(CamelContext.class);
    when(camelContext.getRestConfiguration()).thenReturn(restConfiguration);
    final OpenAPI openapi = new OpenAPI();
    final RestOpenApiComponent component = new RestOpenApiComponent();
    component.setCamelContext(camelContext);
    final RestOpenApiEndpoint endpoint = new RestOpenApiEndpoint("rest-openapi:getPetById", "getPetById", component, Collections.emptyMap());
    assertThat(endpoint.determineBasePath(openapi)).as("When no base path is specified on component, endpoint or rest configuration it should default to `/`").isEqualTo("/");
    restConfiguration.setContextPath("/rest");
    assertThat(endpoint.determineBasePath(openapi)).as("When base path is specified in REST configuration and not specified in component the base path should be from the REST configuration").isEqualTo("/rest");
    openapi.addServersItem(new Server().url("http://petstore.openapi.io").description("v3 test"));
    component.setBasePath("/component");
    assertThat(endpoint.determineBasePath(openapi)).as("When base path is specified on the component it should take precedence over OpenApi specification and REST configuration").isEqualTo("/component");
    endpoint.setBasePath("/endpoint");
    assertThat(endpoint.determineBasePath(openapi)).as("When base path is specified on the endpoint it should take precedence over any other").isEqualTo("/endpoint");
}

